export const applyEnlightenmentSocietyEditorial = (record: Philosopher): Philosopher => {
  const config = configs[record.id];
  const dateDisplay = dateDisplays[record.id];
  const reviewLock = reviewLocks[record.id];
  return applyModernClusterEditorialConfig(
    record,
    config && dateDisplay && reviewLock
      ? {...config, reviewLock, patch: {...config.patch, dateDisplay}}
      : config,
  );
};
